  "ui.finalDesignFlow.0e94726136": "وصول أدوات الوكيل إلى موصل GitHub عبر Composio؛ تظل روابط المستودعات تعمل باستخدام git المحلي أو GitHub CLI.",
  "ui.finalDesignFlow.723772b0a0": "أضف مفتاح API لـ Composio فقط إذا احتاج هذا المشروع إلى أدوات GitHub عبر الموصل.",
  "ui.finalDesignFlow.21f5844795": "يتوفر موصل GitHub عبر Composio كبديل عندما يتعذّر على هذا الجهاز قراءة المستودع.",
  "ui.finalDesignFlow.f32b39ae4f": "أكمل التفويض في نافذة Composio؛ يظل استيراد GitHub المحلي متاحًا.",
  "ui.finalDesignFlow.2a0d6e82a3": "جارٍ فحص حالة الموصل في الخلفية؛ لم يتم حظر الاستيراد عبر الرابط.",
  "ui.finalDesignFlow.5d652ac7d4": "أعد توصيل موصل GitHub عبر Composio، أو تابع باستخدام git المحلي أو GitHub CLI.",
  "ui.finalDesignFlow.c8f1da9e35": "حدّث نظام التصميم هذا: ",
  "ui.finalDesignFlow.bc0ac039a0": "موصل GitHub عبر Composio متصل بالحساب {account}؛ وهو متاح كبديل عندما يتعذّر على هذا الجهاز قراءة المستودع.",
  "ui.finalQueue.interrupted": "انقطع الإرسال. راجع المحادثة قبل الإرسال مجددًا.",
  "ui.finalQueue.saveFailed": "تعذّر حفظ قائمة الانتظار. تم الاحتفاظ برسالتك في مربع الكتابة.",
  "ui.finalQueue.startFailed": "تعذّر البدء. استأنف عندما تكون جاهزًا.",
  "ui.finalQueue.retry": "راجع المحادثة قبل إعادة المحاولة.",
  "ui.finalQueue.unconfirmed": "تعذّر تأكيد الإرسال. راجع المحادثة قبل الإرسال مجددًا.",
  "ui.finalSideChat.localAgent": "تحتاج الدردشة الجانبية إلى وكيل محلي. اختر واحدًا من الشريط العلوي.",
  "ui.finalExport.printFailed": "فشلت الطباعة. حاول التصدير بصيغة PDF مجددًا أو استخدم نسخة المتصفح.",
  "ui.finalExport.popupBlocked": "حظر المتصفح نافذة التصدير. اسمح بالنوافذ المنبثقة لهذا الموقع في المتصفح، ثم حاول التصدير بصيغة PDF مجددًا.",
  "ui.finalOnboarding.f54f5d4bcd": "إعداداتك",
  "ui.finalOnboarding.7d2d594053": "كيف ترغب في استخدام Pixflow؟",
  "ui.finalOnboarding.bdf73477f9": "وصّل مزوّد API الخاص بك",
  "ui.finalOnboarding.28edc3b8f2": "وصّل اشتراك الذكاء الاصطناعي الخاص بك",
  "ui.finalOnboarding.f9573d1164": "أنت جاهز للإنشاء",
  "ui.finalOnboarding.45ddd1221b": "التحرير في WordPress وGutenberg مجاني. لا يلزم ترخيص أو فترة تجريبية.",
  "ui.finalOnboarding.6072f06060": "فعّل ترخيصك للبدء. هل فعّلته بالفعل؟ سيظهر ترخيصك هنا.",
  "ui.finalOnboarding.ae83bc42b4": "اختر ما يناسبك. يمكنك تغيير ذلك في أي وقت من الإعدادات.",
  "ui.finalOnboarding.c9e2eb7fcb": "استخدم مفتاح API من مزوّدك. لا تحتاج هذه الطريقة إلى Bridge.",
  "ui.finalOnboarding.5add76d77c": "يربط Bridge هذا الموقع بوكلاء الذكاء الاصطناعي على جهازك. يُستخدم حساب مزوّدك لتوفير خدمات الذكاء الاصطناعي.",
  "ui.finalOnboarding.4813d31d25": "استخدم مساحة عمل WordPress دون توصيل الذكاء الاصطناعي.",
  "ui.finalOnboarding.fbcd710247": "تم إعداد اتصالك. ابدأ بسؤال أو صف ما تريد إنشاءه.",
  "ui.finalOnboarding.24fba6f166": "توصيل اشتراك ذكاء اصطناعي",
  "ui.finalOnboarding.82d6b8daef": "استخدم وكلاء مدعومين مثل Codex أو OpenCode عبر Pixflow Design Bridge.",
  "ui.finalOnboarding.894f66ba11": "استخدام مفتاح API",
  "ui.finalOnboarding.e76c3bfd0e": "اتصل بمزوّدك مباشرةً. تُحتسب رسوم استخدام API بشكل منفصل.",
  "ui.finalOnboarding.1be451ef72": "المتابعة دون ذكاء اصطناعي",
  "ui.finalOnboarding.88e6e83b86": "استخدم مساحة عمل WordPress. يمكنك إضافة الذكاء الاصطناعي لاحقًا إذا رغبت.",
  "ui.finalOnboarding.105e56e56f": "لماذا تختار CLI المحلي؟",
  "ui.finalOnboarding.5df057fcd7": "تُحتسب رسوم استخدام API بشكل منفصل",
  "ui.finalOnboarding.44e30ed15f": "يتطلب BYOK مفتاح API. يحاسب مزوّد الذكاء الاصطناعي على استخدام API بشكل منفصل عن اشتراك CLI، لذا قد تترتب تكلفة إضافية بدلًا من استهلاك الحدود المضمّنة أو الأسبوعية لحساب CLI.",
  "ui.finalOnboarding.5f9b0ae108": "هذه الجلسة فقط",
  "ui.finalOnboarding.3c0e1f05da": "احتفظ بالسياق فقط أثناء فتح جلسة اللوحة هذه. تبدأ إعادة التحميل من جديد.",
  "ui.finalOnboarding.3efe5537cf": "الاستعادة بعد إعادة التحميل",
  "ui.finalOnboarding.1ccaa4f4ad": "استعد سياقًا محدودًا بعد إعادة التحميل في تبويب المتصفح هذا.",
  "ui.finalOnboarding.a7f9620cca": "على هذا الجهاز",
  "ui.finalOnboarding.94536fb7d6": "احتفظ بسياق محلي محدود بين عمليات إعادة تشغيل المتصفح على هذا الجهاز.",
  "ui.finalOnboarding.1cd7c231fc": "تم تحديث الاحتفاظ ببيانات اللوحة العائمة.",
  "ui.finalOnboarding.d5c52fc3a8": "تم طلب إعادة ضبط السياق للوحة Bricks المفتوحة.",
  "ui.finalOnboarding.77d3d7f7d3": "تم طلب محادثة جديدة للوحة Bricks المفتوحة.",
  "ui.finalOnboarding.125903ce05": "طُلب مسح سياق المتصفح. تبقى المحادثات المحفوظة.",
